/**
 * @method
 * @name scwin.chk2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chk2 = async function () {
    /* sdd-asis-lifecycle:begin fn_Chk2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    if ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disableYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disableYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disableYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disableYn")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disableYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disableYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "disableYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("disableYn"))))) === 'Y') {
        if (frm.roomTpCd.value === "") {
            await $c.win.alert("간담회 참석여부를 선택해주세요.");
            roomTpCd.focus();
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chk = async function () {
    /* sdd-asis-lifecycle:begin fn_Chk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.eduForm || { elements: [] });
    if (frm.depAirtkClssCd.value !== "") {
        if (frm.depTpCd.value !== "01" || frm.depIndvdlMvYn.value !== "N") {
            await $c.win.alert("서울&단체 이동인 경우에만 선택 가능합니다");
            depAirtkClssCd.focus();
            return false;
        }
    }
    if (frm.depReservprnTpCd.value !== "") {
        if (frm.depTpCd.value === "01") {
            await $c.win.alert("지방 출발시만  선택 가능합니다");
            depReservprnTpCd.focus();
            return false;
        }
    }
    if (frm.destAirtkClssCd.value !== "") {
        if (frm.destTpCd.value !== "01" || frm.destIndvdlMvYn.value !== "N") {
            await $c.win.alert("서울&단체 이동인 경우에만 선택가능합니다");
            destAirtkClssCd.focus();
            return false;
        }
    }
    if (frm.destReservprnTpCd.value !== "") {
        if (frm.destTpCd.value === "01") {
            await $c.win.alert("지방 출발시만  선택 가능합니다");
            destReservprnTpCd.focus();
            return false;
        }
    }
    if (frm.disclsEduEvtAddContn.value !== "") {
        if (frm.disclsEduEvtTpCd.value !== "1") {
            await $c.win.alert("골프 선택시만  작성 가능합니다");
            disclsEduEvtAddContn.focus();
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
